import { PostHog } from 'posthog-node';

const posthog = new PostHog(process.env.POSTHOG_API_KEY!, {
  host: process.env.POSTHOG_HOST ?? 'https://us.i.posthog.com',
  flushAt: 20,    // batch size before auto-flush
  flushInterval: 10000, // ms between auto-flushes
});

// Identify a user with properties
posthog.identify({
  distinctId: 'user-123',
  properties: {
    email: 'jane@example.com',
    plan: 'pro',
    signedUpAt: '2026-01-15',
  },
});

// Track an event
posthog.capture({
  distinctId: 'user-123',
  event: 'checkout_completed',
  properties: {
    orderId: 'order_456',
    totalAmount: 99.99,
    currency: 'USD',
    itemCount: 3,
  },
});

// Check a feature flag
const flagEnabled = await posthog.isFeatureEnabled('new-checkout-flow', 'user-123');
if (flagEnabled) {
  // show new experience
}

// IMPORTANT: flush before process exits (e.g., in serverless)
await posthog.shutdown();
